<script setup lang="ts">
import { computed } from 'vue'; import { useRoute } from 'vue-router'; import { products } from '@ushas/mock-data'; import { useCartStore } from '@/stores/cart'
const product = computed(() => products.find(p => p.slug === useRoute().params.slug) ?? products[0]); const cart = useCartStore()
</script>
<template><section class="section product-detail"><div class="detail-image"><img :src="product.image" :alt="product.name"></div><div class="detail-copy"><p class="eyebrow">{{ product.category }}</p><h1>{{ product.name }}</h1><div class="stars">★★★★★ <span>{{ product.rating }} ({{ product.reviews }} reseñas)</span></div><div class="detail-price">S/ {{ product.price.toFixed(2) }} <s v-if="product.originalPrice">S/ {{ product.originalPrice.toFixed(2) }}</s></div><p>{{ product.description }}</p><span class="stock" :class="{ low: product.stock < 10 }">● {{ product.stock > 10 ? 'En stock' : `Últimas ${product.stock} unidades` }}</span><button class="button dark" @click="cart.add(product)">AGREGAR AL CARRITO</button><div class="benefits"><span>✓ Envíos a todo Perú</span><span>✓ Compra 100% segura</span><span>✓ Productos originales</span></div></div></section></template>
